Ltac hstore1 WR A :=
  lazymatch type of WR with wr_at asegs ?mm ?B ?n =>
    let WRC := fresh "WRC" in let junk := fresh "junk" in let CELL := fresh "CELL" in let SOK := fresh "SOK" in
    assert (WRC : wr_at asegs mm A 1) by (apply (wr_at_sub mm B n); [exact WR| lia| lia| lia]);
    destruct (wr_at_rw_CB mm A 1 WRC ltac:(lia)) as (junk & CELL); change (Z.to_nat 1) with 1%nat in CELL;
    pose proof (rw_cells_store_ok_at asegs mm A [CB 1 junk] 0 (CB 1 junk) 1 (Z_to_bv 64 A) CELL eq_refl eq_refl ltac:(unfold wa; f_equal; lia)) as SOK;
    zstep; clear CELL WRC junk; try store_done
  end.
